import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname } from 'node:path';

const SCHEMA = readFileSync(new URL('./schema.sql', import.meta.url), 'utf8');

export type Db = DatabaseSync;

export function openDb(path: string = process.env.VERITAS_DB_PATH ?? '.veritas/veritas.db'): Db {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec('PRAGMA journal_mode = WAL; PRAGMA foreign_keys = ON;');
  db.exec(SCHEMA);
  return db;
}

import { createHash, randomUUID } from 'node:crypto';
import type { Db } from './db.ts';

export interface Investigation {
  id: string;
  repo_url: string;
  commit_sha: string | null;
  status: 'running' | 'awaiting_approval' | 'done' | 'failed';
  current_state: string;
  started_at: string;
  finished_at: string | null;
}

export interface StepRecord {
  id: number;
  state: string;
  name: string;
  idem_key: string;
  status: 'running' | 'done' | 'failed';
  input_json: string | null;
  output_json: string | null;
  error: string | null;
  started_at: string;
  duration_ms: number | null;
  attempt: number;
}

export interface StepResult<T> {
  output: T;
  /** True when the output came from the journal and the step body did not run. */
  reused: boolean;
}

/** JSON with sorted object keys, so equal inputs always hash the same. */
export function stableJson(value: unknown): string {
  return JSON.stringify(value, (_k, v) =>
    v && typeof v === 'object' && !Array.isArray(v)
      ? Object.fromEntries(Object.entries(v).sort(([a], [b]) => a.localeCompare(b)))
      : v,
  );
}

export function idemKey(state: string, name: string, input: unknown): string {
  return createHash('sha256').update(`${state}\n${name}\n${stableJson(input ?? null)}`).digest('hex');
}

/**
 * Durable record of what an investigation has done. A step that finished is
 * never run again for the same input: its stored output is returned instead.
 */
export class Journal {
  constructor(private readonly db: Db) {}

  createInvestigation(repoUrl: string, initialState: string): Investigation {
    const id = randomUUID();
    this.db
      .prepare('INSERT INTO investigations (id, repo_url, current_state, started_at) VALUES (?, ?, ?, ?)')
      .run(id, repoUrl, initialState, new Date().toISOString());
    return this.getInvestigation(id)!;
  }

  getInvestigation(id: string): Investigation | undefined {
    return this.db.prepare('SELECT * FROM investigations WHERE id = ?').get(id) as Investigation | undefined;
  }

  listInvestigations(): Investigation[] {
    return this.db.prepare('SELECT * FROM investigations ORDER BY started_at DESC').all() as unknown as Investigation[];
  }

  setState(id: string, state: string): void {
    this.db.prepare('UPDATE investigations SET current_state = ? WHERE id = ?').run(state, id);
  }

  setStatus(id: string, status: Investigation['status']): void {
    const finished = status === 'running' ? null : new Date().toISOString();
    this.db.prepare('UPDATE investigations SET status = ?, finished_at = ? WHERE id = ?').run(status, finished, id);
  }

  steps(id: string): StepRecord[] {
    return this.db
      .prepare('SELECT * FROM steps WHERE investigation_id = ? ORDER BY id')
      .all(id) as unknown as StepRecord[];
  }

  async runStep<T>(
    investigationId: string,
    state: string,
    name: string,
    input: unknown,
    fn: () => Promise<T> | T,
  ): Promise<StepResult<T>> {
    const key = idemKey(state, name, input);
    const prior = this.db
      .prepare('SELECT * FROM steps WHERE investigation_id = ? AND idem_key = ?')
      .get(investigationId, key) as StepRecord | undefined;

    if (prior?.status === 'done') {
      return { output: JSON.parse(prior.output_json ?? 'null') as T, reused: true };
    }

    const startedAt = new Date().toISOString();
    if (prior) {
      // A step left 'running' means the process died inside it; 'failed' means it threw. Either way, run again.
      this.db
        .prepare("UPDATE steps SET status = 'running', error = NULL, started_at = ?, attempt = attempt + 1 WHERE id = ?")
        .run(startedAt, prior.id);
    } else {
      this.db
        .prepare(
          "INSERT INTO steps (investigation_id, state, name, idem_key, status, input_json, started_at) VALUES (?, ?, ?, ?, 'running', ?, ?)",
        )
        .run(investigationId, state, name, key, stableJson(input ?? null), startedAt);
    }

    const t0 = Date.now();
    const finish = this.db.prepare(
      'UPDATE steps SET status = ?, output_json = ?, error = ?, duration_ms = ? WHERE investigation_id = ? AND idem_key = ?',
    );
    try {
      const output = await fn();
      finish.run('done', JSON.stringify(output ?? null), null, Date.now() - t0, investigationId, key);
      return { output, reused: false };
    } catch (err) {
      const message = err instanceof Error ? `${err.name}: ${err.message}` : String(err);
      finish.run('failed', null, message, Date.now() - t0, investigationId, key);
      throw err;
    }
  }
}

import { flush, init, shutdown, trace } from 'neatlogs';

type Kind = 'WORKFLOW' | 'CHAIN' | 'TOOL' | 'AGENT';
type Attrs = Record<string, string | number | boolean | undefined>;

let enabled = false;

/** Starts tracing when NEATLOGS_API_KEY is set. Without it every helper is a plain passthrough. */
export async function initTracing(workflowName = 'veritas'): Promise<boolean> {
  const apiKey = process.env.NEATLOGS_API_KEY;
  if (!apiKey || enabled) return enabled;
  await init({ apiKey, workflowName });
  enabled = true;
  return enabled;
}

export function tracingEnabled(): boolean {
  return enabled;
}

export async function shutdownTracing(): Promise<void> {
  if (!enabled) return;
  await flush();
  await shutdown();
  enabled = false;
}

/** Runs fn inside a named span. Attributes are prefixed `veritas.` so they are easy to filter on. */
export async function traced<T>(name: string, kind: Kind, attrs: Attrs, fn: () => Promise<T> | T): Promise<T> {
  if (!enabled) return fn();
  return trace({ name, kind }, async (span) => {
    for (const [k, v] of Object.entries(attrs)) {
      if (v !== undefined) span.setAttribute(`veritas.${k}`, v);
    }
    return fn();
  });
}

const num = (name: string, fallback: number): number => {
  const raw = process.env[name];
  const n = raw ? Number(raw) : NaN;
  return Number.isFinite(n) && n > 0 ? n : fallback;
};

export interface Limits {
  maxAttempts: number;
  cmdTimeoutMs: number;
  investigationTimeoutMs: number;
  maxToolCallsPerStep: number;
  maxTokens: number;
}

export function loadLimits(): Limits {
  return {
    maxAttempts: num('VERITAS_MAX_ATTEMPTS', 3),
    cmdTimeoutMs: num('VERITAS_CMD_TIMEOUT_MS', 5 * 60_000),
    investigationTimeoutMs: num('VERITAS_INVESTIGATION_TIMEOUT_MS', 30 * 60_000),
    maxToolCallsPerStep: num('VERITAS_MAX_TOOL_CALLS', 12),
    maxTokens: num('VERITAS_MAX_TOKENS', 400_000),
  };
}

import type { Journal } from '../state/journal.ts';
import type { Db } from '../state/db.ts';
import type { Limits } from './limits.ts';

export const STATES = [
  'INTAKE',
  'INVENTORY',
  'INTEL',
  'IMPACT',
  'PRIORITIZE',
  'PLAN_REPAIR',
  'BASELINE',
  'PATCH',
  'TEST',
  'DIAGNOSE',
  'VERIFY',
  'REPORT',
  'AWAITING_APPROVAL',
] as const;

export type State = (typeof STATES)[number];

/** Allowed moves. The orchestrator rejects anything else, so a handler bug cannot skip verification. */
export const TRANSITIONS: Record<State, readonly State[]> = {
  INTAKE: ['INVENTORY'],
  INVENTORY: ['INTEL'],
  INTEL: ['IMPACT'],
  IMPACT: ['PRIORITIZE'],
  PRIORITIZE: ['PLAN_REPAIR'],
  PLAN_REPAIR: ['BASELINE', 'REPORT'],
  BASELINE: ['PATCH', 'PLAN_REPAIR', 'REPORT'],
  PATCH: ['TEST'],
  TEST: ['VERIFY', 'DIAGNOSE'],
  DIAGNOSE: ['PATCH', 'PLAN_REPAIR', 'REPORT'],
  VERIFY: ['PLAN_REPAIR', 'REPORT'],
  REPORT: ['AWAITING_APPROVAL'],
  AWAITING_APPROVAL: [],
};

export interface RunContext {
  investigationId: string;
  repoUrl: string;
  db: Db;
  journal: Journal;
  limits: Limits;
  /** Runs a journaled step inside the current state: skipped and reused if it already finished. */
  step<T>(name: string, input: unknown, fn: () => Promise<T> | T): Promise<T>;
}

export type StateHandler = (ctx: RunContext) => Promise<State>;
export type Handlers = Record<Exclude<State, 'AWAITING_APPROVAL'>, StateHandler>;

import type { Db } from '../state/db.ts';
import { Journal, type Investigation } from '../state/journal.ts';
import { traced } from '../observability/neatlogs.ts';
import { loadLimits, type Limits } from './limits.ts';
import { TRANSITIONS, type Handlers, type RunContext, type State } from './states.ts';

export class InvestigationTimeout extends Error {
  constructor(ms: number) {
    super(`Investigation exceeded its ${ms} ms limit`);
    this.name = 'InvestigationTimeout';
  }
}

export interface OrchestratorOptions {
  db: Db;
  handlers: Handlers;
  limits?: Limits;
}

export class Orchestrator {
  private readonly journal: Journal;
  private readonly limits: Limits;

  constructor(private readonly opts: OrchestratorOptions) {
    this.journal = new Journal(opts.db);
    this.limits = opts.limits ?? loadLimits();
  }

  start(repoUrl: string): Investigation {
    return this.journal.createInvestigation(repoUrl, 'INTAKE');
  }

  /**
   * Drives an investigation from its recorded state until it needs approval.
   * Safe to call again after a crash: finished steps are reused from the journal.
   */
  async run(investigationId: string): Promise<Investigation> {
    const inv = this.journal.getInvestigation(investigationId);
    if (!inv) throw new Error(`Unknown investigation ${investigationId}`);
    if (inv.status === 'awaiting_approval' || inv.status === 'done') return inv;

    this.journal.setStatus(investigationId, 'running');
    const deadline = Date.now() + this.limits.investigationTimeoutMs;

    return traced(
      'veritas.investigation',
      'WORKFLOW',
      { investigation_id: investigationId, repo: inv.repo_url, resumed_from: inv.current_state },
      async () => {
        let state = inv.current_state as State;
        try {
          while (state !== 'AWAITING_APPROVAL') {
            if (Date.now() > deadline) throw new InvestigationTimeout(this.limits.investigationTimeoutMs);
            const next = await this.runState(inv, state);
            if (!TRANSITIONS[state].includes(next)) {
              throw new Error(`Illegal transition ${state} -> ${next}`);
            }
            this.journal.setState(investigationId, next);
            state = next;
          }
          this.journal.setStatus(investigationId, 'awaiting_approval');
        } catch (err) {
          this.journal.setStatus(investigationId, 'failed');
          throw err;
        }
        return this.journal.getInvestigation(investigationId)!;
      },
    );
  }

  private runState(inv: Investigation, state: Exclude<State, 'AWAITING_APPROVAL'>): Promise<State> {
    const ctx: RunContext = {
      investigationId: inv.id,
      repoUrl: inv.repo_url,
      db: this.opts.db,
      journal: this.journal,
      limits: this.limits,
      step: async (name, input, fn) => {
        let reused = true;
        const result = await this.journal.runStep(inv.id, state, name, input, () => {
          reused = false;
          return traced(`step.${name}`, 'CHAIN', { state, step: name }, fn);
        });
        if (reused) await traced(`step.${name}`, 'CHAIN', { state, step: name, reused: true }, () => undefined);
        return result.output;
      },
    };
    return traced(`state.${state}`, 'CHAIN', { state }, () => this.opts.handlers[state](ctx));
  }
}

